### Interprétation de la sortie

La cellule confirme l'environnement réellement utilisé sans révéler de chemin machine ni de clé :

- le module local `lean_runner.py` a été trouvé et ses classes importées ;
- les providers OpenAI et Anthropic sont tous deux déclarés `OK` ;
- le client OpenAI utilise le modèle affiché dans la sortie ;
- `LeanRunner` est initialisé sur le backend WSL, et `ProofVerifier` en mode `auto` — la sortie dit exactement `LeanRunner initialise (backend: wsl)` puis `ProofVerifier initialise (backend: auto)` : c'est donc bien le backend WSL qui portera les vérifications, via la délégation du vérifieur au runner.

Les cellules suivantes exécutent donc les appels aux deux providers et vérifient les preuves avec Lean. Cette configuration complète est nécessaire pour que la comparaison finale constitue une mesure réelle plutôt qu'un chemin de simulation.

@dataclass
class VerificationResult:
    """Résultat de la vérification Lean."""
    success: bool
    error_message: Optional[str] = None
    remaining_goals: List[str] = None
    execution_time: float = 0.0

class ProofVerifierAgent:
    """Agent de vérification des preuves."""

    def __init__(self, lean_path: str = "lean"):
        self.lean_path = lean_path
        self.verified_count = 0
        self.failed_count = 0

    def verify(self, theorem: str, proof: str) -> VerificationResult:
        """
        Vérifie une preuve avec Lean.

        Args:
            theorem: L'enonce du théorème
            proof: La preuve proposee (sequence de tactiques)

        Returns:
            Résultat de la vérification
        """
        # Construire le code Lean complet
        lean_code = self._build_lean_code(theorem, proof)

        # Simuler l'exécution Lean
        # (Dans un vrai système, on utiliserait subprocess ou lean-dojo)
        result = self._simulate_lean_execution(lean_code)

        # Mettre a jour les statistiques
        if result.success:
            self.verified_count += 1
        else:
            self.failed_count += 1

        return result

    def _build_lean_code(self, theorem: str, proof: str) -> str:
        """Construit le code Lean complet."""
        return f"""
{theorem} := by
  {proof}
        """.strip()

    def _simulate_lean_execution(self, code: str) -> VerificationResult:
        """
        Simule l'exécution Lean.
        Dans un vrai système, utiliser lean-dojo ou subprocess.
        """
        # Heuristiques simples pour la simulation
        if "rfl" in code or "exact Nat.add_zero" in code:
            return VerificationResult(success=True)
        elif "sorry" in code:
            return VerificationResult(
                success=False,
                error_message="declaration uses 'sorry'"
            )
        else:
            # Simuler une reussite aleatoire
            import random
            if random.random() > 0.3:
                return VerificationResult(success=True)
            else:
                return VerificationResult(
                    success=False,
                    error_message="tactic failed"
                )

    def get_stats(self) -> dict:
        """Retourne les statistiques de vérification."""
        total = self.verified_count + self.failed_count
        return {
            "verified": self.verified_count,
            "failed": self.failed_count,
            "success_rate": self.verified_count / max(total, 1)
        }

